Содержание посвящено модам, ресурс-пакам, модпакам, шейдер-пакам или другим ресурсам, связанным с Minecraft. Пожалуйста, сохраняйте стиль языка приятным для геймеров.# KubeJS Мистическое сельское хозяйство

У проекта две цели: заменить мистические кастомизации и добавить поддержку всех типов рецептов мистического сельского хозяйства.

С помощью этого мода вы можете добавлять рецепты пробуждения, рецепты заклинателя, рецепты инфузии, рецепты переработки семян, рецепты извлечения душ и рецепты создания спавнеров сулиума.

Этот мод имеет события запуска для культур и типов душ мобов, позволяющие получить доступ к соответствующим реестрам. Это означает, что вы можете добавлять культуры и души мобов.
### Добавление рецептов
```javascript
ServerEvents.recipes(event => {
const {awakening,enchanter,infusion,reprocessor,soul_extraction,soulium_spawner} = event.recipes.mysticalagriculture;

    // пробуждение
    awakening(
        "minecraft:gold_ingot", // результат
        "minecraft:iron_ingot", // предмет в середине
        [
            Item.of("minecraft:yellow_dye",40), // может содержать количество
            Item.of("minecraft:yellow_dye",40),
            Item.of("minecraft:yellow_dye",40),
            Item.of("minecraft:yellow_dye",40)
        ], // предметы в сосудах эссенции
        [
            "#minecraft;flowers",
            "#minecraft;flowers",
            "#minecraft;flowers",
            "#minecraft;flowers",
        ] // предметы на постаменте
    );
    // заклинатель
    enchanter(
        "minecraft:sharpness", // результат заклинания, которое будет производиться
        [
            Item.of("minecraft:flint",3),
            Item.of("minecraft:iron_ingot",2)
        ] // массив из 1-2 предметов, может содержать количество
    );
    // инфузия
    infusion(
        "minecraft:emerald", // результат
        "minecraft:diamond", // предмет в середине
        [
            Item.of("minecraft:green_dye",4) // количество распаковывается в несколько предметов
        ] // предметы на постаментах
    );
    // переработчик
    reprocessor(
        "minecraft:iron_ingot", // результат
        "minecraft:compass" // входной предмет
    );
    // извлечение душ
    // конструктор 1
    soul_extraction(
        {
            type:"mysticalagriculture:blaze", 
            souls:30
        }, // души мобов
        "minecraft:magma_cream" // входной предмет
    );
    // конструктор 2
    soul_extraction(
        "mysticalagriculture:zombie", // тип души моба
        0.5, // количество душ
        "minecraft:diamond" // входной предмет
    );
    // спавнер сулиума
    soulium_spawner(
        [
            { 
                entity:"minecraft:zombie",
                weight:100
            },
            {
                entity:"minecraft:iron_golem",
                // вес, если не указан, будет равен 1
            }
        ], // объекты
        [
            Item.of("minecraft:emerald",4) // может содержать количество
        ] // входные предметы
    );
});
```

### Добавление культур
в startup_scripts
```javascript
MysticalAgricultureStartupEvents.crop(event => {
    // здесь вы можете получить доступ к реестру культур через event.registry
    /* методы
    void register(Crop crop);
    void registerTier(CropTier tier);
    void registerType(CropType type);
    List<Crop> getCrops();
    Crop getCropById(ResourceLocation id);
    Crop getCropByName(String name);
    List<CropTier> getTiers();
    CropTier getTierById(ResourceLocation id);
    List<CropType> getTypes();
    CropType getTypeById(ResourceLocation id);
    */
    // обратите внимание, что вы не можете отменить регистрацию культуры, но вы можете отключить их
    // для регистрации культуры вам нужен объект Crop
    const kubium = new Crop(
        "kubejs:kubium", // идентификатор культуры
        "mysticalagriculture:5", // идентификатор или объект уровня культуры
        "mysticalagriculture:resource", // идентификатор или объект типа культуры
        new CropTextures(
            "mysticalagriculture:block/flower_ingot",// текстура цветка
            "mysticalagriculture:item/essence_ingot" // текстура эссенции
            // вы также можете задать текстуру для семян, передав дополнительный аргумент
        ), // текстуры
        "#forge:ingots/kubium" // ингредиент, обратите внимание, что это пользовательский объект, используемый мистическим сельским хозяйством, поэтому он должен быть либо тегом, либо предметом
    );
    const red = new Crop(
        "kubejs:red",
        CropTier.ONE,
        CropType.RESOURCE,
        CropTextures.DUST_CROP_TEXTURES,
        16711680,// цвет в десятичном формате
        "minecraft:red_dye"
    );
    // после создания культур зарегистрируйте их
    event.register(kubium);
    red.setDisplayName(Text.ofString("RED").red());
    event.register(red);
});
```

